// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs, address sender) public {
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        vm.assume(sender != address(0x0));
        vm.assume(sender != address(c));
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0x0));
            vm.assume(tos[i] != address(c));
        }

        // Deploy a mock ERC20 that returns true on transferFrom
        MockERC20 mock = new MockERC20();
        // Use the mock as the contract_address to call
        contract_address = address(mock);

        vm.prank(sender);
        bool success = c.transfer(contract_address, tos, vs);
        assertTrue(success);
    }
}

contract MockERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

