pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        vm.assume(tos.length < 50);
        for(uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0x0));
            vm.assume(tos[i] != address(c));
        }
        bool ok;
        bool ret;
        vm.prank(address(0x1234));
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            ok = false; ret = r;
        } catch {
            ok = true;
        }
        assertTrue(ok || ret);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] calldata tos, uint256[] calldata vs) public {
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        // The call must not revert for the property to be meaningful; we only test successful calls
        bool success;
        vm.prank(address(this));
        try c.transfer(contract_address, tos, vs) returns (bool ret) {
            success = true;
            assertTrue(ret);
        } catch {
            success = false;
        }
        // If it reverted, property vacuously holds; assertTrue on non-revert path covers the rest.
        if (!success) { assertTrue(true); }
    }
}
